--- a/runtime/batching/scheduler.go
+++ b/runtime/batching/scheduler.go
@@ -120,6 +120,34 @@ func pickBatch(...) {
+    // apply aging priority: buckets with older requests get boosted in selection
+    for _, q := range queues {
+        q.score += q.agingScore(now)
+    }
+    // enforce soft cap on batch width to preserve slots for small queues
+    if selected.width > cfg.BatchWidthSoftCap && q.isHighThroughput() {
+        selected.width = cfg.BatchWidthSoftCap
+    }
 }

--- a/runtime/batching/queue_manager.go
+++ b/runtime/batching/queue_manager.go
@@ -45,6 +45,22 @@ func enqueue(req) {
+// maxWaitFlush checks oldest request age and triggers a flush if threshold exceeded
+func (qm *QueueManager) maxWaitFlush() {
+    qm.mu.Lock()
+    defer qm.mu.Unlock()
+    if qm.oldestRequestAge() >= qm.cfg.MaxWaitMs {
+        qm.triggerFlushLocked()
+    }
+}
+
+// timer handling consolidated to avoid races when reset during flush paths
+func (qm *QueueManager) resetTimerLocked() {
+    if qm.timer != nil {
+        qm.timer.Stop()
+    }
+    qm.timer = time.AfterFunc(qm.cfg.TimerInterval, qm.timerCb)
+}

--- a/runtime/tests/batching_scheduler_test.go
+++ b/runtime/tests/batching_scheduler_test.go
@@ -200,6 +200,36 @@ func TestNoStarvationUnderLoad(t *testing.T) {
+    // assert starved queue gets scheduled within max wait
+    start := time.Now()
+    waitTimeout := time.Millisecond * 200
+    for time.Since(start) < waitTimeout {
+        if scheduler.SawRequestFrom("tenant-small") {
+            return
+        }
+        time.Sleep(time.Millisecond * 5)
+    }
+    t.Fatalf("tenant-small was starved beyond max-wait")
 }
